package export_ohrats_rc_plugin_package_source

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"

	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/ohrats_rc_plugin_local_files"
	"wit_component/ohrats_rc_plugin_package_source"
)

// Resolve reads a local WebAssembly component, pinning it by content digest.
func Resolve(scheme string, spec string) witTypes.Result[ohrats_rc_plugin_package_source.PackageArtifact, string] {
	if scheme != "file" {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](
			fmt.Sprintf("local source does not handle %q", scheme))
	}
	read := ohrats_rc_plugin_local_files.Read(spec)
	if read.IsErr() {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](read.Err())
	}
	bytes := read.Ok()
	name, err := componentName(spec)
	if err != nil {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](err.Error())
	}
	sum := sha256.Sum256(bytes)
	return witTypes.Ok[ohrats_rc_plugin_package_source.PackageArtifact, string](
		ohrats_rc_plugin_package_source.PackageArtifact{
			Name:   name,
			Source: "file:" + spec,
			Digest: "sha256:" + hex.EncodeToString(sum[:]),
			Bytes:  bytes,
		})
}

// componentName takes the final path segment without its .wasm suffix and
// requires it to be a safe component name.
func componentName(path string) (string, error) {
	filename := path
	if index := strings.LastIndexAny(filename, "/\\"); index >= 0 {
		filename = filename[index+1:]
	}
	if filename == "" {
		return "", fmt.Errorf("local source has no filename")
	}
	name := strings.TrimSuffix(filename, ".wasm")
	if name == "" || len(name) > 96 || !validComponentName(name) {
		return "", fmt.Errorf("invalid component filename %q", filename)
	}
	return name, nil
}

func validComponentName(value string) bool {
	for index := 0; index < len(value); index++ {
		byte := value[index]
		if (byte >= 'a' && byte <= 'z') || (byte >= 'A' && byte <= 'Z') || (byte >= '0' && byte <= '9') {
			continue
		}
		switch byte {
		case '-', '_', '.':
			continue
		}
		return false
	}
	return true
}
